  Status_Id  BIGINT Default 0 NOT NULL,                -- الحالة
  Curn_Id    BIGINT NOT NULL,                          -- العملة
  Acc_Id     BIGINT NOT NULL,                          -- الحساب
  Doc_Id     BIGINT Default 0 NOT NULL,                -- نوع المستند
  BCurn_Id   BIGINT Default 1,                         -- عملة الأساس
  BCurn_Rate DECIMAL(25,8) Default 1,                      -- سعر الصرف
